 entry['process_log'].append(dict(timestamp=datetime.now(timezone.utc).isoformat(),step=step,action=action,inputs=refs('fit-hat.py')+[ref(SOURCE/'source-packet.json'),ref(SOURCE/'model.json')]+extra_inputs,outputs=outputs,review=review,result='PASS',new_imagegen_call=False))
