event('review_game_scale_and_palette','Inspected intended-size facings and separated pale y hat/blue b band; illustrative body tint remains independent.',refs('game-scale-review.png','independent-palette-comparison.png','authoring-review.json'))
event('reprocess_under_regional_curved_v1','Reconciled this body-specific fitting under the full-source, fixed-body, late-visibility recipe. A single constrained head-relative transform sufficed; no unnecessary regional warp.',refs('source-packet.json','model.json','artifact-manifest.json'))
entry.update(status='UNFINISHED',generation_ready=True,current_step='native_equipment_state_review',current_registration=dict(model=ref(HERE/'model.json'),plate=ref(HERE/'headwear-comparison.png')),art_review=dict(status='PASS',reason=review),registration_summary='Canonical hat fitted whole to male head with recorded controls; original body/contact and separate native band tint retained. Native acceptance pending.',native_acceptance='Pending final all-conversions gate');entry['apparel_workflow']['status']='GENERATION READY'
nxt=next(e for e in ledger['entries'] if e['id']=='FIT-NIMA-WIDE-BRIMMED-HAT-HEAD-0');assert not nxt['generation_ready'] and nxt['status']=='UNFINISHED';nxt.update(status='IN PROGRESS',current_step='source_identity_description_slot_laterality');ledger['active_entry']=nxt['id'];ledger['updated_at']=datetime.now(timezone.utc).isoformat();write(lp,ledger)
